Aight, lemme break it down quick — run Dijkstra from 1, keep a parent for each node, then rebuild the path to n. If dist[n] stayin' infinite, print -1. This handles loops and multiple edges fine. Complexity: O((n + m) log n). Here’s a clean C++ implementation you can use:

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = 9e18;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n,m;
    if(!(cin>>n>>m)) return 0;
    vector<vector<pair<int,int>>> adj(n+1);
    for(int i=0;i<m;i++){
        int a,b,w; cin>>a>>b>>w;
        adj[a].push_back({b,w});
        adj[b].push_back({a,w});
    }

    vector<ll> dist(n+1, INF);
    vector<int> par(n+1, -1);
    priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;

    dist[1] = 0;
    pq.push({0,1});

    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d != dist[u]) continue;
        if(u == n) break; // optional early stop
        for(auto &ed : adj[u]){
            int v = ed.first;
            int w = ed.second;
            if(dist[v] > d + w){
                dist[v] = d + w;
                par[v] = u;
                pq.push({dist[v], v});
            }
        }
    }

    if(dist[n] == INF){
        cout << -1 << '\n';
        return 0;
    }

    vector<int> path;
    for(int v = n; v != -1; v = par[v]) path.push_back(v);
    reverse(path.begin(), path.end());

    for(size_t i = 0; i < path.size(); ++i){
        if(i) cout << ' ';
        cout << path[i];
    }
    cout << '\n';
    return 0;
}

Run that on your input and it’ll print a shortest path from 1 to n (or -1 if ain’t no path).

Aight, lemme break it down quick and give you code you can run. Idea real simple: every triangle edge might show up on the black/white border except parts covered by other triangles. So for each triangle edge we: collect all intersection points with other edges (and endpoints), split that edge into small subsegments, pick a tiny point just inside the triangle and a tiny point just outside for each subsegment, check if the inside point’s black and the outside point’s white. If so that subsegment counts. Sum lengths.

Here’s C++17 code you can drop in and run. It follows that plan, handles floating epsilons, and prints the perimeter with enough precision.

#include <bits/stdc++.h>
using namespace std;

struct P { double x,y; };
const double EPS = 1e-9;

double cross(const P &a, const P &b){ return a.x*b.y - a.y*b.x; }
P operator-(const P &a, const P &b){ return P{a.x-b.x, a.y-b.y}; }
P operator+(const P &a, const P &b){ return P{a.x+b.x, a.y+b.y}; }
P operator*(const P &a, double s){ return P{a.x*s, a.y*s}; }
double norm(const P &a){ return sqrt(a.x*a.x + a.y*a.y); }

bool segInter(const P &A, const P &B, const P &C, const P &D, double &tOut){
    P v = B - A;
    P w = D - C;
    double denom = cross(v, w);
    if (fabs(denom) < EPS){
        // parallel or collinear; per problem edges share at most one point, so just check endpoints
        // check endpoints coincidence
        if (fabs(A.x-C.x) < EPS && fabs(A.y-C.y) < EPS){ tOut = 0.0; return true; }
        if (fabs(A.x-D.x) < EPS && fabs(A.y-D.y) < EPS){ tOut = 0.0; return true; }
        if (fabs(B.x-C.x) < EPS && fabs(B.y-C.y) < EPS){ tOut = 1.0; return true; }
        if (fabs(B.x-D.x) < EPS && fabs(B.y-D.y) < EPS){ tOut = 1.0; return true; }
        return false;
    }
    P AC = C - A;
    double t = cross(AC, w) / denom;
    double u = cross(AC, v) / denom;
    if (t >= -EPS && t <= 1+EPS && u >= -EPS && u <= 1+EPS){
        tOut = max(0.0, min(1.0, t));
        return true;
    }
    return false;
}

bool pointInTri(const P &p, const P &a, const P &b, const P &c){
    // barycentric via cross signs, allow border
    double c1 = cross(b-a, p-a);
    double c2 = cross(c-b, p-b);
    double c3 = cross(a-c, p-c);
    // allow small eps, check same sign or zero
    if ((c1 >= -1e-10 && c2 >= -1e-10 && c3 >= -1e-10) || (c1 <= 1e-10 && c2 <= 1e-10 && c3 <= 1e-10)) return true;
    return false;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n; if (!(cin >> n)) return 0;
    vector<array<P,3>> T(n);
    for (int i=0;i<n;i++){
        for (int j=0;j<3;j++) cin >> T[i][j].x >> T[i][j].y;
    }
    double total = 0.0;
    if (n==0){ cout.setf(ios::fixed); cout << setprecision(10) << 0.0 << '\n'; return 0; }

    for (int i=0;i<n;i++){
        for (int e=0;e<3;e++){
            P A = T[i][e];
            P B = T[i][(e+1)%3];
            P C = T[i][(e+2)%3]; // third vertex to decide interior side
            vector<double> ts;
            ts.push_back(0.0); ts.push_back(1.0);
            // intersect with all triangle edges
            for (int k=0;k<n;k++){
                for (int ee=0; ee<3; ee++){
                    P C1 = T[k][ee];
                    P D1 = T[k][(ee+1)%3];
                    double tinter;
                    if (segInter(A,B,C1,D1,tinter)){
                        if (tinter > -EPS && tinter < 1+EPS) ts.push_back(max(0.0, min(1.0, tinter)));
                    }
                }
            }
            sort(ts.begin(), ts.end());
            // unique with eps
            vector<double> uts;
            for (double v: ts){ if (uts.empty() || v - uts.back() > 1e-8) uts.push_back(v); }
            // edge vector
            P vAB = B - A;
            double lenAB = norm(vAB);
            if (lenAB < EPS) continue;
            // decide outward normal direction: we want vector from interior -> outside
            // if cross(vAB, C-A) > 0 then C is left of AB => interior is left => outward is right => rotate -90
            P rotMinus = P{ vAB.y, -vAB.x }; // rotate -90
            P rotPlus  = P{ -vAB.y, vAB.x }; // rotate +90
            P outN;
            if (cross(vAB, C - A) > 0) outN = rotMinus; else outN = rotPlus;
            double nlen = norm(outN);
            if (nlen < EPS) continue;
            outN = outN * (1.0 / nlen);
            double offset = 1e-7; // small offset

            for (size_t idx=0; idx+1<uts.size(); ++idx){
                double t1 = uts[idx];
                double t2 = uts[idx+1];
                if (t2 - t1 < 1e-12) continue;
                double tm = (t1 + t2) * 0.5;
                P M = A + vAB * tm;
                P outsideP = M + outN * offset;
                P insideP  = M - outN * offset;
                bool insideAny = false;
                bool outsideAny = false;
                for (int k=0;k<n;k++){
                    if (!insideAny && pointInTri(insideP, T[k][0], T[k][1], T[k][2])) insideAny = true;
                    if (!outsideAny && pointInTri(outsideP, T[k][0], T[k][1], T[k][2])) outsideAny = true;
                    if (insideAny && outsideAny) break;
                }
                // we want inside point black and outside point white -> boundary
                if (insideAny && !outsideAny){ total += lenAB * (t2 - t1); }
            }
        }
    }
    cout.setf(ios::fixed); cout << setprecision(10) << total << '\n';
    return 0;
}

