Aight, so you gotchu a circular array and gotta do range updates and range min queries fast. That mean we gon' need a segment tree wit' lazy propagation, and handle the wrapping by splittin' queries if needed. Lemme break it down wit' some C++ code for you:

```cpp
#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9 + 7;

struct SegmentTree {
    int n;
    vector<int> tree, lazy;

    SegmentTree(const vector<int>& a) {
        n = a.size();
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
        build(1, 0, n-1, a);
    }

    void build(int node, int l, int r, const vector<int>& a) {
        if (l == r) {
            tree[node] = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(node*2, l, m, a);
        build(node*2+1, m+1, r, a);
        tree[node] = min(tree[node*2], tree[node*2+1]);
    }

    void push(int node, int l, int r) {
        if (lazy[node]) {
            tree[node] += lazy[node];
            if (l != r) {
                lazy[node*2] += lazy[node];
                lazy[node*2+1] += lazy[node];
            }
            lazy[node] = 0;
        }
    }

    void range_add(int node, int l, int r, int ql, int qr, int val) {
        push(node, l, r);
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            lazy[node] += val;
            push(node, l, r);
            return;
        }
        int m = (l + r) / 2;
        range_add(node*2, l, m, ql, qr, val);
        range_add(node*2+1, m+1, r, ql, qr, val);
        tree[node] = min(tree[node*2], tree[node*2+1]);
    }

    int range_min(int node, int l, int r, int ql, int qr) {
        push(node, l, r);
        if (ql > r || qr < l) return INF;
        if (ql <= l && r <= qr) return tree[node];
        int m = (l + r) / 2;
        return min(range_min(node*2, l, m, ql, qr), range_min(node*2+1, m+1, r, ql, qr));
    }

    void inc(int l, int r, int v) {
        if (l <= r) {
            range_add(1, 0, n-1, l, r, v);
        } else {
            range_add(1, 0, n-1, l, n-1, v);
            range_add(1, 0, n-1, 0, r, v);
        }
    }
    int rmq(int l, int r) {
        if (l <= r) {
            return range_min(1, 0, n-1, l, r);
        } else {
            return min(range_min(1, 0, n-1, l, n-1), range_min(1, 0, n-1, 0, r));
        }
    }
};

int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SegmentTree st(a);
    int m; cin >> m;
    string s;
    getline(cin, s);
    while (m--) {
        getline(cin, s);
        stringstream ss(s);
        int x, y, z;
        if (ss >> x >> y) {
            if (ss >> z) {
                st.inc(x, y, z);
            } else {
                cout << st.rmq(x, y) << '\n';
            }
        }
    }
}
```

