    long long n; cin >> n;
    long long ans = LLONG_MAX;
    for(int k = 1; k <= 10; ++k){ // k up to 10 is plenty
        string s;
        s.append(k, '4');
        s.append(k, '7');
        sort(s.begin(), s.end());
        do{
            // skip permutations that start with '0' ain't possible here, we only got 4/7
            long long val = 0;
            for(char c: s){ val = val*10 + (c - '0'); }
            if(val >= n) ans = min(ans, val);
        } while(next_permutation(s.begin(), s.end()));
        if(ans != LLONG_MAX) break; // found answer, no need to try longer lengths
    }
    cout << ans << '\n';
    return 0;
}

